const pipelineState={view:'kanban',query:'',selected:new Set(),collapsed:new Set(),hidden:new Set(),dialog:null,focusId:null};
const pipelineStages=['Novo Lead','Em Contato','Proposta Enviada','Em Negociação','Fechado','Perdido'];
const pipelineStageOf=c=>pipelineStages.includes(c.stage)?c.stage:({'Em contato':'Em Contato','Proposta':'Proposta Enviada','Negociação':'Em Negociação','Fechado':'Fechado'}[c.stage]||'Novo Lead');
function pipelineClients(){const q=pipelineState.query.toLocaleLowerCase('pt-BR');return clientsState.items.filter(c=>!c.archived&&(!pipelineState.focusId||c.id===pipelineState.focusId)&&(!q||[c.name,c.email,c.phone,c.company,c.project,...(c.tags||[])].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(q))))}
function pipelineCard(c){return `<article class="pipeline-lead" draggable="true" data-lead-id="${esc(c.id)}" tabindex="0" aria-label="Abrir ${esc(c.name)}"><div class="pipeline-lead-title"><span class="pipeline-avatar">${esc(c.name.slice(0,1).toUpperCase())}</span><strong>${esc(c.name)}</strong><button type="button" data-pipeline="edit" data-id="${esc(c.id)}" aria-label="Editar ${esc(c.name)}">⋮</button></div><small>◷ Entrou em ${formatDate(c.start)}</small><small>▣ ${esc(c.project||'Sem projeto')}</small><small>✉ ${esc(c.email||'Sem e-mail')}</small><small>♧ ${esc(c.phone||'Sem telefone')}</small><div>${(c.tags||[]).map(t=>`<span class="pipeline-tag">${esc(t)}</span>`).join('')}</div><span class="pipeline-estimate">Valor estimado<strong>${money(c.monthly)}</strong></span><div class="pipeline-lead-actions"><button type="button" data-pipeline="won" data-id="${esc(c.id)}">✓ Ganha</button><button type="button" data-pipeline="lost" data-id="${esc(c.id)}">⊗ Perdida</button></div><button class="pipeline-open" type="button" data-pipeline="open" data-id="${esc(c.id)}">Abrir</button></article>`}
function renderPipeline(){const w=document.querySelector('.workspace');w.classList.remove('clients-mode','technical-mode','dashboard-mode','kanban-mode','leads-mode');w.classList.add('pipeline-mode');document.querySelector('#page-title').textContent='Pipelines';const rows=pipelineClients();w.innerHTML=`<div class="pipeline-shell"><header class="pipeline-head"><h2>Leads & Clientes</h2><p>Gerencie seu funil de vendas</p><div class="pipeline-toolbar"><button class="pipeline-primary" data-pipeline="new">＋ Novo Lead</button><button data-pipeline="negotiation">⟳ Nova Negociação</button><button data-pipeline="all">♧ Todos os Leads</button><button data-pipeline="results">▥ Ver resultados</button><button data-pipeline="automatic">◯ Lead automático</button><span class="pipeline-spacer"></span><button data-pipeline="manage">☷ Gerenciar</button></div></header><div class="pipeline-view"><strong>Pipeline Principal</strong>${pipelineState.focusId?`<button data-pipeline="clear-focus">${esc(clientsState.items.find(c=>c.id===pipelineState.focusId)?.name||"Cliente")} ×</button>`:""}<span class="pipeline-spacer"></span><button class="${pipelineState.view==='kanban'?'active':''}" data-pipeline="kanban">▦ Kanban</button><button class="${pipelineState.view==='list'?'active':''}" data-pipeline="list">☷ Lista</button></div><div class="pipeline-filters"><label>⌕ <input id="pipeline-search" type="search" placeholder="Buscar por nome, e-mail, telefone ou tag..." value="${esc(pipelineState.query)}"></label><span class="pipeline-spacer"></span><button data-pipeline="select">☑ Selecionar</button><button data-pipeline="collapse">${pipelineState.collapsed.size?'Expandir':'Recolher'} cards</button></div><div class="pipeline-board ${pipelineState.view==='list'?'as-list':''}">${pipelineStages.filter(stage=>!pipelineState.hidden.has(stage)).map(stage=>{const cards=rows.filter(c=>pipelineStageOf(c)===stage),sum=cards.reduce((n,c)=>n+(Number(c.monthly)||0),0);return `<section class="pipeline-column" data-stage="${esc(stage)}"><div class="pipeline-column-head"><div><h3>${stage}</h3><small>${money(sum)}</small></div><span>${cards.length}</span></div><div class="pipeline-dropzone">${pipelineState.collapsed.has(stage)?`<button class="pipeline-expand" data-pipeline="expand" data-stage="${esc(stage)}">Mostrar ${cards.length} ${cards.length===1?'card':'cards'}</button>`:cards.length?cards.map(pipelineCard).join(''):'<div class="pipeline-empty">Arraste leads para cá</div>'}</div></section>`}).join('')}</div><p class="pipeline-note">As alterações do funil ficam nesta sessão. Os clientes e suas etapas aparecem também na aba Clientes.</p></div>`}
function pipelineSetStage(id,stage){const c=clientsState.items.find(c=>c.id===id);if(!c||!pipelineStages.includes(stage))return;c.stage=stage;if(typeof dashActivity==='function')dashActivity('Negociação atualizada: '+c.name+' · '+stage,c.id);renderPipeline();toast(`${c.name}: ${stage}.`)}
function pipelineForm(id){const c=clientsState.items.find(c=>c.id===id);const layer=document.createElement('div');layer.className='pipeline-dialog';layer.innerHTML=`<form id="pipeline-form" role="dialog" aria-modal="true" aria-label="${c?'Editar lead':'Novo lead'}"><div class="pipeline-dialog-head"><h2>${c?'Editar lead':'Novo lead'}</h2><button type="button" data-pipeline="close" aria-label="Fechar">×</button></div><label>Nome *<input name="name" required maxlength="120" value="${esc(c?.name)}" placeholder="Nome do lead"></label><label>E-mail<input name="email" type="email" value="${esc(c?.email)}"></label><label>Telefone<input name="phone" type="tel" value="${esc(c?.phone)}"></label><label>Projeto ou serviço<input name="project" value="${esc(c?.project)}"></label><div class="pipeline-form-pair"><label>Etapa<select name="stage">${pipelineStages.map(s=>`<option ${pipelineStageOf(c||{})===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Valor estimado (R$)<input name="monthly" type="number" min="0" step="0.01" value="${esc(c?.monthly||'')}"></label></div><div class="pipeline-dialog-actions"><button type="button" data-pipeline="close">Cancelar</button><button class="pipeline-primary" type="submit">Salvar lead</button></div></form>`;layer.dataset.id=id||'';document.body.append(layer);layer.querySelector('[name=name]').focus()}
function pipelineInfo(title,body){const layer=document.createElement('div');layer.className='pipeline-dialog';layer.innerHTML=`<div class="pipeline-info" role="dialog" aria-modal="true"><div class="pipeline-dialog-head"><h2>${title}</h2><button data-pipeline="close" aria-label="Fechar">×</button></div>${body}</div>`;document.body.append(layer)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-pipeline]');if(!b){const card=e.target.closest('.pipeline-lead');if(card&&document.querySelector('.pipeline-mode'))openModal('details',card.dataset.leadId);if(e.target.classList.contains('pipeline-dialog'))e.target.remove();return}const a=b.dataset.pipeline,id=b.dataset.id;if(a==='close'){b.closest('.pipeline-dialog')?.remove();return}if(!document.querySelector('.pipeline-mode'))return;if(['new','negotiation','edit'].includes(a))pipelineForm(id);else if(a==='open')openModal('details',id);else if(a==='won'||a==='lost')pipelineSetStage(id,a==='won'?'Fechado':'Perdido');else if(a==='kanban'||a==='list'){pipelineState.view=a;renderPipeline()}else if(a==='clear-focus'){pipelineState.focusId=null;renderPipeline()}else if(a==='all'){pipelineState.focusId=null;pipelineState.query='';pipelineState.hidden.clear();pipelineState.collapsed.clear();renderPipeline()}else if(a==='collapse'){pipelineState.collapsed=pipelineState.collapsed.size?new Set():new Set(pipelineStages);renderPipeline()}else if(a==='expand'){pipelineState.collapsed.delete(b.dataset.stage);renderPipeline()}else if(a==='results'){const rows=pipelineClients(),won=rows.filter(c=>pipelineStageOf(c)==='Fechado');pipelineInfo('Resultados do funil',`<div class="pipeline-results"><div>Leads ativos<strong>${rows.length}</strong></div><div>Negócios fechados<strong>${won.length}</strong></div><div>Valor fechado<strong>${money(won.reduce((n,c)=>n+(Number(c.monthly)||0),0))}</strong></div></div>`)}else if(a==='manage')pipelineInfo('Gerenciar etapas',`<p>Escolha as etapas exibidas no quadro.</p>${pipelineStages.map(s=>`<label class="pipeline-check"><input type="checkbox" data-pipeline-stage="${esc(s)}" ${pipelineState.hidden.has(s)?'':'checked'}> ${s}</label>`).join('')}`);else if(a==='automatic')pipelineInfo('Lead automático','<p>A captura automática depende de uma integração de formulários. Cadastre leads pelo botão Novo Lead.</p>');else if(a==='select')pipelineInfo('Selecionar leads','<p>Abra um cartão para visualizar ou editar o cliente. Você também pode arrastá-lo para outra etapa.</p>')});
document.addEventListener('input',e=>{if(e.target.id==='pipeline-search'){pipelineState.query=e.target.value;const pos=e.target.selectionStart;renderPipeline();const input=document.querySelector('#pipeline-search');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-pipeline-stage]')){if(e.target.checked)pipelineState.hidden.delete(e.target.dataset.pipelineStage);else pipelineState.hidden.add(e.target.dataset.pipelineStage);renderPipeline();e.target.closest('.pipeline-dialog')?.remove()}});
document.addEventListener('submit',e=>{if(e.target.id!=='pipeline-form')return;e.preventDefault();const root=e.target.closest('.pipeline-dialog'),v=Object.fromEntries(new FormData(e.target)),name=v.name.trim();if(!name)return;let c=clientsState.items.find(c=>c.id===root.dataset.id);if(c)Object.assign(c,{name,email:v.email.trim(),phone:v.phone.trim(),project:v.project.trim(),stage:v.stage,monthly:Number(v.monthly)||0});else clientsState.items.unshift({id:String(Date.now()),name,email:v.email.trim(),phone:v.phone.trim(),company:'',project:v.project.trim(),stage:v.stage,monthly:Number(v.monthly)||0,start:new Date().toISOString().slice(0,10),createdAt:new Date().toISOString(),origin:'Cadastro manual',months:'',pipeline:'Pipeline Principal',tags:[],archived:false,contacts:[]});if(typeof dashActivity==='function')dashActivity((root.dataset.id?'Lead editado: ':'Lead criado: ')+name,c.id);root.remove();renderPipeline();toast('Lead salvo nesta sessão.')});
document.addEventListener('dragstart',e=>{const card=e.target.closest('.pipeline-lead');if(card){e.dataTransfer.setData('text/plain',card.dataset.leadId);e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('.pipeline-column');if(zone){e.preventDefault();zone.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const zone=e.target.closest('.pipeline-column');if(zone&&!zone.contains(e.relatedTarget))zone.classList.remove('drag-over')});
document.addEventListener('drop',e=>{const zone=e.target.closest('.pipeline-column');if(zone){e.preventDefault();pipelineSetStage(e.dataTransfer.getData('text/plain'),zone.dataset.stage)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.pipeline-lead')){e.preventDefault();openModal('details',e.target.dataset.leadId)}if(e.key==='Escape')document.querySelector('.pipeline-dialog')?.remove()});
